// Generated subset of DejaVu Sans (Bitstream Vera + public domain additions,
// free to use) carrying the ASCII range plus the rupee sign U+20B9, so jsPDF
// can render the ₹ amounts in exported reports. Do not edit by hand; rebuild
// with: fontTools.subset <font> --unicodes="U+0020-007E,U+00B7,U+2014,U+2022,U+20B9,U+221A".

const NORMAL = "";
const BOLD = "";

/** Register the rupee-capable fonts on a fresh jsPDF instance. */
export function registerPdfFonts(doc: {
  addFileToVFS(filename: string, filecontent: string): void;
  addFont(postScriptName: string, id: string, fontStyle: string): void;
}): void {
  doc.addFileToVFS("rupee.ttf", NORMAL);
  doc.addFileToVFS("rupee-bold.ttf", BOLD);
  doc.addFont("rupee.ttf", "rupee", "normal");
  doc.addFont("rupee-bold.ttf", "rupee", "bold");
}

/** True when the current jsPDF instance has the rupee fonts registered. */
export const PDF_FONTS_AVAILABLE = true;
